    { const char * tb_v484 = "TB_API void tb_vga_font(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v484; }
    { const char * tb_v485 = "    tb_outw(0x3C4, 0x0402); tb_outw(0x3C4, 0x0704);   // пишем в слой шрифта\n"; *(const char * *)tb_grow(v_lines) = tb_v485; }
