    { const char * tb_v490 = "    tb_outw(0x3C4, 0x0302); tb_outw(0x3C4, 0x0304);   // обратно в текстовый режим\n"; *(const char * *)tb_grow(v_lines) = tb_v490; }
    { const char * tb_v491 = "    tb_outw(0x3CE, 0x0004); tb_outw(0x3CE, 0x1005); tb_outw(0x3CE, 0x0E06);\n"; *(const char * *)tb_grow(v_lines) = tb_v491; }
    { const char * tb_v492 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v492; }
    { const char * tb_v493 = "TB_API unsigned char tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v493; }
    { const char * tb_v494 = "TB_API void tb_putc(char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v494; }
    { const char * tb_v495 = "    unsigned char ch = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v495; }
    { const char * tb_v496 = "    while ((tb_inb(0x3F8 + 5) & 0x20) == 0) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v496; }
    { const char * tb_v497 = "    tb_outb(0x3F8, ch);   // в порт — как есть (UTF-8)\n"; *(const char * *)tb_grow(v_lines) = tb_v497; }
    { const char * tb_v498 = "    if (ch < 0x80) { tb_utf_lead = 0; tb_vga_put(ch); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v498; }
    { const char * tb_v499 = "    if (ch >= 0xC0) { tb_utf_lead = ch; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v499; }
    { const char * tb_v500 = "    // второй байт: А..я = U+0410..U+044F, Ё = U+0401, ё = U+0451\n"; *(const char * *)tb_grow(v_lines) = tb_v500; }
    { const char * tb_v501 = "    unsigned cp = ((unsigned)(tb_utf_lead & 0x1F) << 6) | (ch & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v501; }
    { const char * tb_v502 = "    if (tb_utf_lead == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v502; }
    { const char * tb_v503 = "    tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v503; }
    { const char * tb_v504 = "    if (cp >= 0x410 && cp <= 0x44F) tb_vga_put((unsigned char)(128 + cp - 0x410));\n"; *(const char * *)tb_grow(v_lines) = tb_v504; }
    { const char * tb_v505 = "    else if (cp == 0x401) tb_vga_put(128 + 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v505; }
    { const char * tb_v506 = "    else if (cp == 0x451) tb_vga_put(128 + 65);\n"; *(const char * *)tb_grow(v_lines) = tb_v506; }
    { const char * tb_v507 = "    else tb_vga_put('?');\n"; *(const char * *)tb_grow(v_lines) = tb_v507; }
    { const char * tb_v508 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v508; }
    { const char * tb_v509 = "TB_API int fputs(const char *s, FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v509; }
    { const char * tb_v510 = "    uint64_t fl = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v510; }
