    { const char * tb_v512 = "    if (f == stderr) tb_vcolor = 0x0C;   // ошибки — красным\n"; *(const char * *)tb_grow(v_lines) = tb_v512; }
    { const char * tb_v513 = "    while (*s) tb_putc(*s++);\n"; *(const char * *)tb_grow(v_lines) = tb_v513; }
    { const char * tb_v514 = "    tb_vcolor = was;\n"; *(const char * *)tb_grow(v_lines) = tb_v514; }
