    { const char * tb_v522 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v522; }
    { const char * tb_v523 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v523; }
    { const char * tb_v524 = "    tb_outb(0xF4, (unsigned char)code);\n"; *(const char * *)tb_grow(v_lines) = tb_v524; }
