    { const char * tb_v699 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v699; }
    { const char * tb_v700 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v700; }
    { const char * tb_v701 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v701; }
    { const char * tb_v702 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v702; }
