    { const char * tb_v704 = "    snprintf(buf, sizeof buf, \"\\n*** ядро остановлено: %s (0x%llx, 0x%llx)\\n\", what, (unsigned long long)a, (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v704; }
    { const char * tb_v705 = "    fputs(buf, stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v705; }
