    { const char * tb_v709 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v709; }
    { const char * tb_v710 = "TB_API uint64_t tb_gdt[5] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL, 0, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v710; }
    { const char * tb_v711 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v711; }
    { const char * tb_v712 = "typedef struct __attribute__((packed)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v712; }
