    { const char * tb_v753 = "TB_API int tb_cur = 0, tb_nlive = 1, tb_slice = 10, tb_in_irq = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v753; }
    { const char * tb_v754 = "TB_API unsigned char tb_tls_zero[TB_TLS_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v754; }
    { const char * tb_v755 = "TB_API unsigned char tb_fpu_init[512] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v755; }
    { const char * tb_v756 = "TB_API unsigned char tb_irq_tls[TB_TLS_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v756; }
    { const char * tb_v757 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v757; }
    { const char * tb_v758 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v758; }
    { const char * tb_v759 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v759; }
    { const char * tb_v760 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v760; }
    { const char * tb_v761 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v761; }
    { const char * tb_v762 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v762; }
    { const char * tb_v763 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v763; }
    { const char * tb_v764 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v764; }
    { const char * tb_v765 = "    tb_pic_mask &= (uint16_t)~(1u << (v - 32));\n"; *(const char * *)tb_grow(v_lines) = tb_v765; }
    { const char * tb_v766 = "    if (v >= 40) tb_pic_mask &= (uint16_t)~(1u << 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v766; }
    { const char * tb_v767 = "    tb_pic_apply();\n"; *(const char * *)tb_grow(v_lines) = tb_v767; }
    { const char * tb_v768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v768; }
    { const char * tb_v769 = "TB_API void tb_irq_on(void) { __asm__ volatile(\"sti\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v769; }
    { const char * tb_v770 = "TB_API void tb_irq_off(void) { __asm__ volatile(\"cli\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v770; }
    { const char * tb_v771 = "TB_API void tb_yield(void) { if (!tb_in_irq) __asm__ volatile(\"int $48\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v771; }
    { const char * tb_v772 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v772; }
    { const char * tb_v773 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v773; }
    { const char * tb_v774 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v774; }
    { const char * tb_v775 = "    if (tb_nlive <= 1 && !tb_slots[tb_cur].done) return frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v775; }
    { const char * tb_v776 = "    int n = tb_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v776; }
    { const char * tb_v777 = "    for (int k = 1; k <= TB_NTASK; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v777; }
    { const char * tb_v778 = "        int j = (tb_cur + k) % TB_NTASK;\n"; *(const char * *)tb_grow(v_lines) = tb_v778; }
    { const char * tb_v779 = "        if (tb_slots[j].used && !tb_slots[j].done) { n = j; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v779; }
    { const char * tb_v780 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v780; }
    { const char * tb_v781 = "    tb_kslot *c = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v781; }
    { const char * tb_v782 = "    if (n == tb_cur) return frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v782; }
    { const char * tb_v783 = "    c->frame = frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v783; }
    { const char * tb_v784 = "    memcpy(c->tls, tb_tls_start, tb_tls_size());\n"; *(const char * *)tb_grow(v_lines) = tb_v784; }
    { const char * tb_v785 = "    if (c->done) { c->used = 0; tb_nlive--; }\n"; *(const char * *)tb_grow(v_lines) = tb_v785; }
    { const char * tb_v786 = "    tb_cur = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v786; }
    { const char * tb_v787 = "    memcpy(tb_tls_start, tb_slots[n].tls, tb_tls_size());\n"; *(const char * *)tb_grow(v_lines) = tb_v787; }
    { const char * tb_v788 = "    tb_slice = 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v788; }
    { const char * tb_v789 = "    return tb_slots[n].frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v789; }
    { const char * tb_v790 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v790; }
    { const char * tb_v791 = "TB_API void tb_task_entry(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v791; }
    { const char * tb_v792 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v792; }
    { const char * tb_v793 = "    s->run(s->arg);\n"; *(const char * *)tb_grow(v_lines) = tb_v793; }
    { const char * tb_v794 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v794; }
    { const char * tb_v795 = "    s->t->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v795; }
    { const char * tb_v796 = "    s->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v796; }
    { const char * tb_v797 = "    for (;;) __asm__ volatile(\"int $48\");\n"; *(const char * *)tb_grow(v_lines) = tb_v797; }
    { const char * tb_v798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v798; }
    { const char * tb_v799 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v799; }
    { const char * tb_v800 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v800; }
    { const char * tb_v801 = "    int i = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v801; }
    { const char * tb_v802 = "    while (i < TB_NTASK && tb_slots[i].used) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v802; }
    { const char * tb_v803 = "    if (i == TB_NTASK) tb_panic(\"больше 31 задачи background сразу\", 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v803; }
    { const char * tb_v804 = "    tb_kslot *s = &tb_slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v804; }
    { const char * tb_v805 = "    s->used = 1; s->done = 0; s->run = run; s->arg = arg; s->t = t;\n"; *(const char * *)tb_grow(v_lines) = tb_v805; }
    { const char * tb_v806 = "    t->done = 0; t->th = i;\n"; *(const char * *)tb_grow(v_lines) = tb_v806; }
    { const char * tb_v807 = "    memcpy(s->tls, tb_tls_zero, TB_TLS_MAX);\n"; *(const char * *)tb_grow(v_lines) = tb_v807; }
    { const char * tb_v808 = "    // стек задачи выглядит так, будто её прервали прямо перед tb_task_entry\n"; *(const char * *)tb_grow(v_lines) = tb_v808; }
    { const char * tb_v809 = "    unsigned char *top = tb_tstacks[i] + TB_TSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v809; }
    { const char * tb_v810 = "    uint64_t *fr = (uint64_t *)(top - TB_FRAME);\n"; *(const char * *)tb_grow(v_lines) = tb_v810; }
    { const char * tb_v811 = "    memset(fr, 0, TB_FRAME);\n"; *(const char * *)tb_grow(v_lines) = tb_v811; }
    { const char * tb_v812 = "    memcpy(fr, tb_fpu_init, 512);\n"; *(const char * *)tb_grow(v_lines) = tb_v812; }
    { const char * tb_v813 = "    fr[TB_F_RIP] = (uint64_t)(uintptr_t)tb_task_entry;\n"; *(const char * *)tb_grow(v_lines) = tb_v813; }
    { const char * tb_v814 = "    fr[TB_F_RIP + 1] = 0x08;                       // cs\n"; *(const char * *)tb_grow(v_lines) = tb_v814; }
    { const char * tb_v815 = "    fr[TB_F_RIP + 2] = 0x202;                      // rflags: прерывания включены\n"; *(const char * *)tb_grow(v_lines) = tb_v815; }
    { const char * tb_v816 = "    fr[TB_F_RIP + 3] = (uint64_t)(uintptr_t)(top - 8);   // rsp: как после call\n"; *(const char * *)tb_grow(v_lines) = tb_v816; }
    { const char * tb_v817 = "    fr[TB_F_RIP + 4] = 0x10;                       // ss\n"; *(const char * *)tb_grow(v_lines) = tb_v817; }
    { const char * tb_v818 = "    s->frame = fr;\n"; *(const char * *)tb_grow(v_lines) = tb_v818; }
    { const char * tb_v819 = "    tb_nlive++;\n"; *(const char * *)tb_grow(v_lines) = tb_v819; }
