    { const char * tb_v1263 = "// подсказки для clang / gcc: ошибка бывает редко, а tb_crash не возвращается\n"; *(const char * *)tb_grow(v_lines) = tb_v1263; }
    { const char * tb_v1264 = "#if defined(__GNUC__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1264; }
