    { const char * tb_v1271 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
    { const char * tb_v1273 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v1273; }
    { const char * tb_v1274 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1274; }
    { const char * tb_v1275 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1275; }
    { const char * tb_v1276 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1276; }
    { const char * tb_v1277 = "    if (tb_cell_can_fall()) tb_cell_fall(msg, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v1277; }
    { const char * tb_v1278 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1278; }
    { const char * tb_v1279 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1279; }
    { const char * tb_v1280 = "    // в терминале — красным (если не задан NO_COLOR)\n"; *(const char * *)tb_grow(v_lines) = tb_v1280; }
