    { const char * tb_v1320 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1320; }
    { const char * tb_v1321 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1321; }
    { const char * tb_v1322 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1322; }
