    { const char * tb_v1405 = "// начало программы на Windows: русский текст в консоли, цвета, слова запуска в UTF-8,\n"; *(const char * *)tb_grow(v_lines) = tb_v1405; }
    { const char * tb_v1406 = "// понятное сообщение при переполнении стека\n"; *(const char * *)tb_grow(v_lines) = tb_v1406; }
    { const char * tb_v1407 = "TB_API void tb_win_init(int *argc, char ***argv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1407; }
    { const char * tb_v1408 = "    SetConsoleOutputCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1408; }
