    { const char * tb_v1439 = "TB_API void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1439; }
    { const char * tb_v1440 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v1440; }
