    { const char * tb_v1537 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1537; }
    { const char * tb_v1538 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1538; }
    { const char * tb_v1539 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1539; }
    { const char * tb_v1540 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1540; }
    { const char * tb_v1541 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1541; }
    { const char * tb_v1542 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1542; }
    { const char * tb_v1543 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1543; }
    { const char * tb_v1544 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1544; }
    { const char * tb_v1545 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1545; }
    { const char * tb_v1546 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1546; }
    { const char * tb_v1547 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1547; }
    { const char * tb_v1548 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1548; }
    { const char * tb_v1549 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1549; }
    { const char * tb_v1550 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1550; }
    { const char * tb_v1551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1551; }
    { const char * tb_v1552 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1552; }
    { const char * tb_v1553 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1553; }
    { const char * tb_v1554 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1554; }
    { const char * tb_v1555 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1555; }
    { const char * tb_v1556 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1556; }
    { const char * tb_v1557 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1557; }
    { const char * tb_v1558 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1558; }
    { const char * tb_v1559 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1559; }
    { const char * tb_v1560 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v1560; }
    { const char * tb_v1561 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1561; }
    { const char * tb_v1562 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1562; }
    { const char * tb_v1563 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v1563; }
    { const char * tb_v1564 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v1564; }
    { const char * tb_v1565 = "#define TB_GNC 37\n"; *(const char * *)tb_grow(v_lines) = tb_v1565; }
    { const char * tb_v1566 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v1566; }
    { const char * tb_v1567 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v1567; }
    { const char * tb_v1568 = "TB_API const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v1568; }
    { const char * tb_v1569 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v1569; }
    { const char * tb_v1570 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v1570; }
    { const char * tb_v1571 = "typedef struct tb_gpage {\n"; *(const char * *)tb_grow(v_lines) = tb_v1571; }
    { const char * tb_v1572 = "    char *start;\n"; *(const char * *)tb_grow(v_lines) = tb_v1572; }
    { const char * tb_v1573 = "    long long bsize, nblocks;      // мелкие: размер блока и сколько их\n"; *(const char * *)tb_grow(v_lines) = tb_v1573; }
    { const char * tb_v1574 = "    long long nbytes, cap;         // большой блок: сколько занято и сколько взято\n"; *(const char * *)tb_grow(v_lines) = tb_v1574; }
    { const char * tb_v1575 = "    unsigned long long inv;        // 2^32 / bsize (вверх): номер блока умножением, без деления\n"; *(const char * *)tb_grow(v_lines) = tb_v1575; }
    { const char * tb_v1576 = "    int large, cls, in_avail, np;  // np: внутри нет адресов (числа, тексты) — обход туда не смотрит\n"; *(const char * *)tb_grow(v_lines) = tb_v1576; }
    { const char * tb_v1577 = "    unsigned char *fl;             // по байту на блок: 1 — занят, 2 — нужен (найден при обходе)\n"; *(const char * *)tb_grow(v_lines) = tb_v1577; }
    { const char * tb_v1578 = "    unsigned char lfl;             // то же для большого блока\n"; *(const char * *)tb_grow(v_lines) = tb_v1578; }
    { const char * tb_v1579 = "    void *free; long long nfree, bump;   // bump: блоки с этого номера ещё ни разу не брали (там нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v1579; }
    { const char * tb_v1580 = "    struct tb_gpage *next, *prev, *anext;\n"; *(const char * *)tb_grow(v_lines) = tb_v1580; }
    { const char * tb_v1581 = "} tb_gpage;\n"; *(const char * *)tb_grow(v_lines) = tb_v1581; }
    { const char * tb_v1582 = "typedef struct { char *p; long long n; } tb_grange;\n"; *(const char * *)tb_grow(v_lines) = tb_v1582; }
    { const char * tb_v1583 = "TB_API unsigned char tb_gcls[TB_GBIG / 8 + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1583; }
    { const char * tb_v1584 = "TB_API tb_gpage *tb_gall = 0, *tb_glarge = 0, *tb_gavail[2][TB_GNC];\n"; *(const char * *)tb_grow(v_lines) = tb_v1584; }
    { const char * tb_v1585 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v1585; }
    { const char * tb_v1586 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v1586; }
    { const char * tb_v1587 = "TB_API uintptr_t tb_glo = ~(uintptr_t)0, tb_ghi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1587; }
    { const char * tb_v1588 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1588; }
    { const char * tb_v1589 = "TB_API int tb_gready = 0, tb_goff = 0, tb_gstats = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1589; }
    { const char * tb_v1590 = "TB_API char *tb_gtop = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1590; }
    { const char * tb_v1591 = "TB_API pthread_mutex_t tb_glock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v1591; }
    { const char * tb_v1592 = "TB_API tb_grange *tb_groots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1592; }
    { const char * tb_v1593 = "TB_API long long tb_gnroots = 0, tb_gcaproots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1593; }
    { const char * tb_v1594 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1594; }
    { const char * tb_v1595 = "TB_API void tb_gsetup(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1595; }
    { const char * tb_v1596 = "    int c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1596; }
    { const char * tb_v1597 = "    for (long long i = 0; i <= TB_GBIG / 8; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1597; }
    { const char * tb_v1598 = "        while (tb_gsz[c] < i * 8) c++;\n"; *(const char * *)tb_grow(v_lines) = tb_v1598; }
    { const char * tb_v1599 = "        tb_gcls[i] = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v1599; }
    { const char * tb_v1600 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1600; }
    { const char * tb_v1601 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1601; }
    { const char * tb_v1602 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1602; }
    { const char * tb_v1603 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1603; }
    { const char * tb_v1604 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1604; }
    { const char * tb_v1605 = "    tb_gpage **l2 = tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v1605; }
    { const char * tb_v1606 = "    return l2 ? l2[(a >> TB_GSH) & 0xFFFF] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1606; }
    { const char * tb_v1607 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1607; }
    { const char * tb_v1608 = "TB_API void tb_gmap_put(uintptr_t a, tb_gpage *pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1608; }
    { const char * tb_v1609 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v1609; }
    { const char * tb_v1610 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1610; }
    { const char * tb_v1611 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v1611; }
    { const char * tb_v1612 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1612; }
    { const char * tb_v1613 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1613; }
    { const char * tb_v1614 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1614; }
    { const char * tb_v1615 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1615; }
    { const char * tb_v1616 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1616; }
    { const char * tb_v1617 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1617; }
    { const char * tb_v1618 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v1618; }
    { const char * tb_v1619 = "    if ((uintptr_t)pg->start + size > tb_ghi) tb_ghi = (uintptr_t)pg->start + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v1619; }
    { const char * tb_v1620 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1620; }
    { const char * tb_v1621 = "TB_API void tb_gmap_remove(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1621; }
    { const char * tb_v1622 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1622; }
    { const char * tb_v1623 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1623; }
    { const char * tb_v1624 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v1624; }
    { const char * tb_v1625 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1625; }
    { const char * tb_v1626 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v1626; }
    { const char * tb_v1627 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v1627; }
    { const char * tb_v1628 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1628; }
    { const char * tb_v1629 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v1629; }
    { const char * tb_v1630 = "    if (!m) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1630; }
    { const char * tb_v1631 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1631; }
    { const char * tb_v1632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1632; }
    { const char * tb_v1633 = "#define munmap(p, n) (VirtualFree((p), 0, MEM_RELEASE) ? 0 : -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v1633; }
    { const char * tb_v1634 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1634; }
    { const char * tb_v1635 = "#include <sys/mman.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1635; }
    { const char * tb_v1636 = "#ifdef __linux__\n"; *(const char * *)tb_grow(v_lines) = tb_v1636; }
    { const char * tb_v1637 = "#ifndef MREMAP_MAYMOVE\n"; *(const char * *)tb_grow(v_lines) = tb_v1637; }
    { const char * tb_v1638 = "#define MREMAP_MAYMOVE 1\n"; *(const char * *)tb_grow(v_lines) = tb_v1638; }
    { const char * tb_v1639 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1639; }
    { const char * tb_v1640 = "#ifndef MREMAP_FIXED\n"; *(const char * *)tb_grow(v_lines) = tb_v1640; }
    { const char * tb_v1641 = "#define MREMAP_FIXED 2\n"; *(const char * *)tb_grow(v_lines) = tb_v1641; }
    { const char * tb_v1642 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1642; }
    { const char * tb_v1643 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v1643; }
    { const char * tb_v1644 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1644; }
    { const char * tb_v1645 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1645; }
    { const char * tb_v1646 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v1646; }
    { const char * tb_v1647 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1647; }
    { const char * tb_v1648 = "    if (m == MAP_FAILED) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1648; }
    { const char * tb_v1649 = "    uintptr_t a = ((uintptr_t)m + TB_GPG - 1) & ~(uintptr_t)(TB_GPG - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1649; }
    { const char * tb_v1650 = "    if (a > (uintptr_t)m) munmap(m, a - (uintptr_t)m);\n"; *(const char * *)tb_grow(v_lines) = tb_v1650; }
    { const char * tb_v1651 = "    size_t tail = (uintptr_t)m + tot - (a + (size_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1651; }
    { const char * tb_v1652 = "    if (tail) munmap((char *)a + size, tail);\n"; *(const char * *)tb_grow(v_lines) = tb_v1652; }
    { const char * tb_v1653 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1653; }
    { const char * tb_v1654 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1654; }
    { const char * tb_v1655 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1655; }
    { const char * tb_v1656 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v1656; }
    { const char * tb_v1657 = "TB_API char *tb_gfresh = 0, *tb_gfresh_end = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1657; }
    { const char * tb_v1658 = "TB_API void *tb_gspare = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1658; }
    { const char * tb_v1659 = "TB_API char *tb_gpage_mem(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1659; }
    { const char * tb_v1660 = "    if (tb_gspare) { void *p = tb_gspare; tb_gspare = *(void **)p; *(void **)p = 0; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1660; }
    { const char * tb_v1661 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1661; }
    { const char * tb_v1662 = "    char *p = tb_gfresh;\n"; *(const char * *)tb_grow(v_lines) = tb_v1662; }
    { const char * tb_v1663 = "    tb_gfresh += TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v1663; }
    { const char * tb_v1664 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1664; }
    { const char * tb_v1665 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1665; }
    { const char * tb_v1666 = "TB_API tb_gpage *tb_gnewpage(int cls, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1666; }
    { const char * tb_v1667 = "    tb_gpage *pg = calloc(1, sizeof(tb_gpage));\n"; *(const char * *)tb_grow(v_lines) = tb_v1667; }
    { const char * tb_v1668 = "    if (!pg) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1668; }
    { const char * tb_v1669 = "    pg->start = tb_gpage_mem();\n"; *(const char * *)tb_grow(v_lines) = tb_v1669; }
    { const char * tb_v1670 = "    pg->cls = cls; pg->np = np; pg->bsize = tb_gsz[cls]; pg->nblocks = TB_GPG / pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v1670; }
    { const char * tb_v1671 = "    pg->inv = ((1ULL << 32) + pg->bsize - 1) / pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v1671; }
    { const char * tb_v1672 = "    pg->fl = calloc(pg->nblocks, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1672; }
    { const char * tb_v1673 = "    if (!pg->fl) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1673; }
    { const char * tb_v1674 = "    pg->free = 0; pg->bump = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1674; }
    { const char * tb_v1675 = "    pg->nfree = pg->nblocks;\n"; *(const char * *)tb_grow(v_lines) = tb_v1675; }
    { const char * tb_v1676 = "    pg->next = tb_gall; tb_gall = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1676; }
    { const char * tb_v1677 = "    tb_gmap_add(pg, TB_GPG);\n"; *(const char * *)tb_grow(v_lines) = tb_v1677; }
