    { const char * tb_v2767 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2767; }
    { const char * tb_v2768 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2768; }
    { const char * tb_v2769 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2769; }
    { const char * tb_v2770 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2770; }
    { const char * tb_v2771 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2771; }
    { const char * tb_v2772 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2772; }
