    { const char * tb_v2786 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
