    { const char * tb_v2789 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
