    { const char * tb_v2795 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2795; }
    { const char * tb_v2796 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2796; }
