    { const char * tb_v2961 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
