    { const char * tb_v2973 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2973; }
    { const char * tb_v2974 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2974; }
    { const char * tb_v2975 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
    { const char * tb_v2977 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2977; }
    { const char * tb_v2978 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2978; }
