    { const char * tb_v2981 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2981; }
    { const char * tb_v2982 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2982; }
    { const char * tb_v2983 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2983; }
    { const char * tb_v2984 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2984; }
    { const char * tb_v2985 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2985; }
    { const char * tb_v2986 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2986; }
    { const char * tb_v2987 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
    { const char * tb_v2988 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2988; }
    { const char * tb_v2989 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2989; }
