    { const char * tb_v2991 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2991; }
    { const char * tb_v2992 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2992; }
