    { const char * tb_v3001 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3001; }
    { const char * tb_v3002 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3002; }
    { const char * tb_v3003 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3003; }
