    { const char * tb_v3010 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3010; }
    { const char * tb_v3011 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3011; }
    { const char * tb_v3012 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3012; }
    { const char * tb_v3013 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3013; }
    { const char * tb_v3014 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3014; }
    { const char * tb_v3015 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3015; }
    { const char * tb_v3016 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3016; }
    { const char * tb_v3017 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
    { const char * tb_v3019 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
    { const char * tb_v3021 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3021; }
    { const char * tb_v3022 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3022; }
    { const char * tb_v3023 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3023; }
    { const char * tb_v3024 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3024; }
    { const char * tb_v3025 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3025; }
    { const char * tb_v3026 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3026; }
    { const char * tb_v3027 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3027; }
    { const char * tb_v3028 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3028; }
    { const char * tb_v3029 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3029; }
    { const char * tb_v3030 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3030; }
    { const char * tb_v3031 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3031; }
    { const char * tb_v3032 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
    { const char * tb_v3035 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
    { const char * tb_v3038 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3038; }
    { const char * tb_v3039 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3039; }
    { const char * tb_v3040 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3040; }
    { const char * tb_v3041 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3041; }
    { const char * tb_v3042 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3042; }
    { const char * tb_v3043 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3043; }
    { const char * tb_v3044 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3044; }
    { const char * tb_v3045 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3045; }
    { const char * tb_v3046 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
    { const char * tb_v3047 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3047; }
    { const char * tb_v3048 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
    { const char * tb_v3049 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
    { const char * tb_v3050 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3050; }
    { const char * tb_v3051 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3051; }
    { const char * tb_v3052 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3052; }
    { const char * tb_v3053 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3053; }
    { const char * tb_v3054 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3054; }
    { const char * tb_v3055 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3055; }
    { const char * tb_v3056 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3056; }
    { const char * tb_v3057 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3057; }
    { const char * tb_v3058 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3058; }
    { const char * tb_v3059 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3059; }
    { const char * tb_v3060 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3060; }
    { const char * tb_v3061 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3061; }
    { const char * tb_v3062 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3062; }
    { const char * tb_v3063 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
    { const char * tb_v3064 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3064; }
    { const char * tb_v3065 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
    { const char * tb_v3066 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3066; }
    { const char * tb_v3067 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3067; }
    { const char * tb_v3068 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3068; }
    { const char * tb_v3069 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3069; }
    { const char * tb_v3070 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3070; }
    { const char * tb_v3071 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3071; }
    { const char * tb_v3072 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3072; }
    { const char * tb_v3073 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3073; }
    { const char * tb_v3074 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3074; }
    { const char * tb_v3075 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3075; }
    { const char * tb_v3076 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
    { const char * tb_v3080 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3080; }
    { const char * tb_v3081 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
    { const char * tb_v3087 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
    { const char * tb_v3088 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3088; }
    { const char * tb_v3089 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3089; }
    { const char * tb_v3090 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3090; }
    { const char * tb_v3091 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3091; }
    { const char * tb_v3092 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3092; }
    { const char * tb_v3093 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3093; }
    { const char * tb_v3094 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3094; }
    { const char * tb_v3095 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
    { const char * tb_v3097 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v3097; }
    { const char * tb_v3098 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
    { const char * tb_v3099 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3099; }
    { const char * tb_v3100 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3100; }
    { const char * tb_v3101 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3101; }
    { const char * tb_v3102 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3102; }
    { const char * tb_v3103 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v3103; }
    { const char * tb_v3104 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3104; }
    { const char * tb_v3105 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v3105; }
    { const char * tb_v3106 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3106; }
    { const char * tb_v3107 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3107; }
    { const char * tb_v3108 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3108; }
    { const char * tb_v3109 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3109; }
    { const char * tb_v3110 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3110; }
    { const char * tb_v3111 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3111; }
    { const char * tb_v3112 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3112; }
    { const char * tb_v3113 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3113; }
    { const char * tb_v3114 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3114; }
    { const char * tb_v3115 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3115; }
    { const char * tb_v3116 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3116; }
    { const char * tb_v3117 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3117; }
    { const char * tb_v3118 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3118; }
    { const char * tb_v3119 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3119; }
    { const char * tb_v3120 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3120; }
    { const char * tb_v3121 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3121; }
    { const char * tb_v3122 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3122; }
    { const char * tb_v3123 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3123; }
    { const char * tb_v3124 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3124; }
    { const char * tb_v3125 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3125; }
    { const char * tb_v3126 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3126; }
    { const char * tb_v3127 = "TB_INL long long tb_bnot(long long a) { return ~a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3127; }
    { const char * tb_v3128 = "TB_INL long long tb_shl(long long a, long long n) { return (long long)((unsigned long long)a << (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3128; }
    { const char * tb_v3129 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3129; }
    { const char * tb_v3130 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "// shared x += n без замка. В ядре без ОС одно ядро процессора: хватает выключить прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
    { const char * tb_v3133 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3133; }
    { const char * tb_v3134 = "static inline void tb_atomic_addd(volatile double *p, double v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
    { const char * tb_v3136 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3136; }
    { const char * tb_v3137 = "// дробь: сравнить и заменить, пока никто не успел поменять\n"; *(const char * *)tb_grow(v_lines) = tb_v3137; }
    { const char * tb_v3138 = "static inline void tb_atomic_addd(volatile double *p, double v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3138; }
    { const char * tb_v3139 = "    volatile uint64_t *q = (volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "    uint64_t old = __atomic_load_n(q, __ATOMIC_SEQ_CST), nw;\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
    { const char * tb_v3142 = "        union { uint64_t u; double d; } a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3142; }
    { const char * tb_v3143 = "        a.u = old; b.d = a.d + v; nw = b.u;\n"; *(const char * *)tb_grow(v_lines) = tb_v3143; }
    { const char * tb_v3144 = "    } while (!__atomic_compare_exchange_n(q, &old, nw, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST));\n"; *(const char * *)tb_grow(v_lines) = tb_v3144; }
    { const char * tb_v3145 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3145; }
    { const char * tb_v3146 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3146; }
    { const char * tb_v3147 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3147; }
    { const char * tb_v3148 = "// ---------- память руками: new_mem, free_mem, grow_mem, copy_mem, fill_mem (только в danger) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3148; }
    { const char * tb_v3149 = "// Перед каждым блоком 16 байт: размер и метка «живой» / «освобождён» — так free_mem ловит чужой\n"; *(const char * *)tb_grow(v_lines) = tb_v3149; }
    { const char * tb_v3150 = "// адрес и второе освобождение. TB_MEM_CHECK=1 (не в ядре): за блоком 16 байт-сторожей, освобождённые\n"; *(const char * *)tb_grow(v_lines) = tb_v3150; }
    { const char * tb_v3151 = "// блоки не отдаются обратно (их чтение и запись ловятся), read/write/copy_mem/fill_mem проверяют\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "// адрес, а в конце программы печатается, что не освобождено\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "#define TB_MEM_LIVE 0x4D454D4C49564521ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
