    { const char * tb_v3291 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"grow_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3291; }
    { const char * tb_v3292 = "    tb_memh *h = tb_mem_own(a, line, \"grow_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3292; }
