    { const char * tb_v4011 = "    if (!px) { free(z.out); *why = \"не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4011; }
    { const char * tb_v4012 = "    unsigned char *prev = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4012; }
    { const char * tb_v4013 = "    for (unsigned y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4013; }
