    { const char * tb_v6881 = "// window_sharp в X11: масштаб из настройки Xft.dpi (её ставят GNOME и KDE), иначе 1\n"; *(const char * *)tb_grow(v_lines) = tb_v6881; }
    { const char * tb_v6882 = "TB_API double tb_gfx_scale(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "    if (!tb_dpy) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "    const char *v = XGetDefault(tb_dpy, \"Xft\", \"dpi\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
