    { const char * tb_v7014 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7014; }
    { const char * tb_v7015 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7015; }
    { const char * tb_v7016 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7016; }
