    { const char * tb_v7027 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7027; }
    { const char * tb_v7028 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v7028; }
