    { const char * tb_v7124 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7124; }
    { const char * tb_v7125 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7125; }
    { const char * tb_v7126 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7126; }
    { const char * tb_v7127 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7127; }
    { const char * tb_v7128 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v7128; }
    { const char * tb_v7129 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7129; }
    { const char * tb_v7130 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7130; }
    { const char * tb_v7131 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7131; }
