    { const char * tb_v7164 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
    { const char * tb_v7171 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7171; }
    { const char * tb_v7172 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v7172; }
    { const char * tb_v7173 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7173; }
    { const char * tb_v7174 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7174; }
    { const char * tb_v7175 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7175; }
    { const char * tb_v7176 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
    { const char * tb_v7178 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7178; }
    { const char * tb_v7179 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
    { const char * tb_v7181 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7181; }
    { const char * tb_v7182 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7182; }
    { const char * tb_v7183 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7183; }
    { const char * tb_v7184 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7184; }
    { const char * tb_v7185 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7185; }
    { const char * tb_v7186 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7186; }
    { const char * tb_v7187 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7187; }
    { const char * tb_v7188 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7188; }
    { const char * tb_v7189 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7189; }
    { const char * tb_v7190 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7190; }
    { const char * tb_v7191 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7191; }
    { const char * tb_v7192 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v7192; }
    { const char * tb_v7193 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7193; }
    { const char * tb_v7194 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v7194; }
    { const char * tb_v7195 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7195; }
    { const char * tb_v7196 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7196; }
    { const char * tb_v7197 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7197; }
    { const char * tb_v7198 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7198; }
    { const char * tb_v7199 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7199; }
    { const char * tb_v7200 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7200; }
    { const char * tb_v7201 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7201; }
    { const char * tb_v7202 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7202; }
    { const char * tb_v7203 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v7203; }
    { const char * tb_v7204 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7204; }
    { const char * tb_v7205 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v7205; }
    { const char * tb_v7206 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
    { const char * tb_v7208 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7208; }
    { const char * tb_v7209 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7209; }
    { const char * tb_v7210 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7210; }
    { const char * tb_v7211 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7211; }
    { const char * tb_v7212 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7212; }
    { const char * tb_v7213 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v7213; }
    { const char * tb_v7214 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7214; }
    { const char * tb_v7215 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7215; }
    { const char * tb_v7216 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
    { const char * tb_v7217 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v7217; }
    { const char * tb_v7218 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v7218; }
    { const char * tb_v7219 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v7219; }
    { const char * tb_v7220 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
    { const char * tb_v7222 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7222; }
    { const char * tb_v7223 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7223; }
    { const char * tb_v7224 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7224; }
    { const char * tb_v7225 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
    { const char * tb_v7227 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7227; }
    { const char * tb_v7228 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7228; }
    { const char * tb_v7229 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7229; }
    { const char * tb_v7230 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7230; }
    { const char * tb_v7231 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7231; }
    { const char * tb_v7232 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7232; }
    { const char * tb_v7233 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7233; }
    { const char * tb_v7234 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7234; }
    { const char * tb_v7235 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7235; }
    { const char * tb_v7236 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7236; }
    { const char * tb_v7237 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v7237; }
    { const char * tb_v7238 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
    { const char * tb_v7240 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
