    { const char * tb_v7266 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
