    { const char * tb_v7292 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
