    { const char * tb_v7297 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7297; }
    { const char * tb_v7298 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
    { const char * tb_v7301 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v7301; }
    { const char * tb_v7302 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
    { const char * tb_v7303 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7303; }
    { const char * tb_v7304 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7304; }
    { const char * tb_v7305 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7305; }
    { const char * tb_v7306 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
