    { const char * tb_v7336 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7336; }
    { const char * tb_v7337 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7337; }
