    { const char * tb_v7339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
    { const char * tb_v7341 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v7341; }
    { const char * tb_v7342 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7342; }
    { const char * tb_v7343 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7343; }
    { const char * tb_v7344 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7344; }
    { const char * tb_v7345 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7345; }
    { const char * tb_v7346 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7346; }
    { const char * tb_v7347 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v7347; }
    { const char * tb_v7348 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7348; }
    { const char * tb_v7349 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7349; }
    { const char * tb_v7350 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7350; }
    { const char * tb_v7351 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v7351; }
    { const char * tb_v7352 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7352; }
    { const char * tb_v7353 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7353; }
    { const char * tb_v7354 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7354; }
    { const char * tb_v7355 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7355; }
    { const char * tb_v7356 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7356; }
    { const char * tb_v7357 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7357; }
    { const char * tb_v7358 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7358; }
    { const char * tb_v7359 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7359; }
    { const char * tb_v7360 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7360; }
