    { const char * tb_v7612 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7612; }
    { const char * tb_v7613 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7613; }
    { const char * tb_v7614 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7614; }
    { const char * tb_v7615 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7615; }
    { const char * tb_v7616 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7616; }
    { const char * tb_v7617 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7617; }
    { const char * tb_v7618 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7618; }
    { const char * tb_v7619 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7619; }
    { const char * tb_v7620 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7620; }
    { const char * tb_v7621 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7621; }
    { const char * tb_v7622 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7622; }
    { const char * tb_v7623 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v7623; }
    { const char * tb_v7624 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7624; }
    { const char * tb_v7625 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7625; }
    { const char * tb_v7626 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7626; }
    { const char * tb_v7627 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7627; }
    { const char * tb_v7628 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7628; }
    { const char * tb_v7629 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7629; }
    { const char * tb_v7630 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7630; }
