    { const char * tb_v7898 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
    { const char * tb_v7899 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v7899; }
    { const char * tb_v7900 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v7900; }
    { const char * tb_v7901 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v7901; }
    { const char * tb_v7902 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v7902; }
    { const char * tb_v7903 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v7903; }
    { const char * tb_v7904 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v7904; }
    { const char * tb_v7905 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v7905; }
    { const char * tb_v7906 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v7906; }
    { const char * tb_v7907 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v7907; }
    { const char * tb_v7908 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v7908; }
    { const char * tb_v7909 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7909; }
    { const char * tb_v7910 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7910; }
    { const char * tb_v7911 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v7911; }
    { const char * tb_v7912 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v7912; }
    { const char * tb_v7913 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v7913; }
    { const char * tb_v7914 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7914; }
    { const char * tb_v7915 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v7915; }
    { const char * tb_v7916 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7916; }
    { const char * tb_v7917 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7917; }
    { const char * tb_v7918 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v7918; }
    { const char * tb_v7919 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7919; }
    { const char * tb_v7920 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v7920; }
    { const char * tb_v7921 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v7921; }
    { const char * tb_v7922 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7922; }
    { const char * tb_v7923 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v7923; }
    { const char * tb_v7924 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7924; }
    { const char * tb_v7925 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v7925; }
    { const char * tb_v7926 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7926; }
    { const char * tb_v7927 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7927; }
    { const char * tb_v7928 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7928; }
    { const char * tb_v7929 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v7929; }
    { const char * tb_v7930 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7930; }
    { const char * tb_v7931 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7931; }
    { const char * tb_v7932 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7932; }
    { const char * tb_v7933 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7933; }
    { const char * tb_v7934 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7934; }
    { const char * tb_v7935 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7935; }
    { const char * tb_v7936 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7936; }
    { const char * tb_v7937 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v7937; }
    { const char * tb_v7938 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7938; }
    { const char * tb_v7939 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v7939; }
    { const char * tb_v7940 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7940; }
    { const char * tb_v7941 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7941; }
    { const char * tb_v7942 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v7942; }
    { const char * tb_v7943 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7943; }
    { const char * tb_v7944 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7944; }
    { const char * tb_v7945 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7945; }
    { const char * tb_v7946 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7946; }
    { const char * tb_v7947 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7947; }
    { const char * tb_v7948 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7948; }
    { const char * tb_v7949 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v7949; }
    { const char * tb_v7950 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7950; }
    { const char * tb_v7951 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7951; }
    { const char * tb_v7952 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v7952; }
    { const char * tb_v7953 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7953; }
    { const char * tb_v7954 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7954; }
    { const char * tb_v7955 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7955; }
    { const char * tb_v7956 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7956; }
    { const char * tb_v7957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7957; }
    { const char * tb_v7958 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v7958; }
    { const char * tb_v7959 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7959; }
    { const char * tb_v7960 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7960; }
    { const char * tb_v7961 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7961; }
    { const char * tb_v7962 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7962; }
    { const char * tb_v7963 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7963; }
    { const char * tb_v7964 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7964; }
    { const char * tb_v7965 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7965; }
    { const char * tb_v7966 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7966; }
    { const char * tb_v7967 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v7967; }
    { const char * tb_v7968 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v7968; }
    { const char * tb_v7969 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v7969; }
    { const char * tb_v7970 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7970; }
    { const char * tb_v7971 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7971; }
    { const char * tb_v7972 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v7972; }
    { const char * tb_v7973 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7973; }
    { const char * tb_v7974 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7974; }
    { const char * tb_v7975 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7975; }
    { const char * tb_v7976 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7976; }
    { const char * tb_v7977 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v7977; }
    { const char * tb_v7978 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7978; }
    { const char * tb_v7979 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7979; }
    { const char * tb_v7980 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7980; }
    { const char * tb_v7981 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v7981; }
    { const char * tb_v7982 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7982; }
    { const char * tb_v7983 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7983; }
    { const char * tb_v7984 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7984; }
    { const char * tb_v7985 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v7985; }
    { const char * tb_v7986 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v7986; }
    { const char * tb_v7987 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7987; }
    { const char * tb_v7988 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7988; }
    { const char * tb_v7989 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7989; }
    { const char * tb_v7990 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7990; }
    { const char * tb_v7991 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7991; }
    { const char * tb_v7992 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v7992; }
    { const char * tb_v7993 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7993; }
    { const char * tb_v7994 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v7994; }
    { const char * tb_v7995 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v7995; }
    { const char * tb_v7996 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7996; }
    { const char * tb_v7997 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7997; }
    { const char * tb_v7998 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7998; }
    { const char * tb_v7999 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7999; }
    { const char * tb_v8000 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8000; }
    { const char * tb_v8001 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8001; }
    { const char * tb_v8002 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8002; }
    { const char * tb_v8003 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v8003; }
    { const char * tb_v8004 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8004; }
    { const char * tb_v8005 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8005; }
    { const char * tb_v8006 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8006; }
    { const char * tb_v8007 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8007; }
    { const char * tb_v8008 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8008; }
    { const char * tb_v8009 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8009; }
    { const char * tb_v8010 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8010; }
    { const char * tb_v8011 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8011; }
    { const char * tb_v8012 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8012; }
    { const char * tb_v8013 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8013; }
    { const char * tb_v8014 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8014; }
    { const char * tb_v8015 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8015; }
    { const char * tb_v8016 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v8016; }
    { const char * tb_v8017 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8017; }
    { const char * tb_v8018 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8018; }
    { const char * tb_v8019 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8019; }
    { const char * tb_v8020 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8020; }
    { const char * tb_v8021 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8021; }
    { const char * tb_v8022 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v8022; }
    { const char * tb_v8023 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8023; }
    { const char * tb_v8024 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8024; }
    { const char * tb_v8025 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8025; }
    { const char * tb_v8026 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8026; }
    { const char * tb_v8027 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8027; }
    { const char * tb_v8028 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v8028; }
    { const char * tb_v8029 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8029; }
    { const char * tb_v8030 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8030; }
    { const char * tb_v8031 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8031; }
    { const char * tb_v8032 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8032; }
    { const char * tb_v8033 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8033; }
    { const char * tb_v8034 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8034; }
    { const char * tb_v8035 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v8035; }
    { const char * tb_v8036 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8036; }
